import {open,readFile,mkdir,lstat,rename,unlink} from 'node:fs/promises';
import {randomUUID} from 'node:crypto';
import path from 'node:path';
import os from 'node:os';

export function configPath() {return process.env.CREW_CONFIG??path.join(os.homedir(),'.config','crew','config.json');}
export function validateServerUrl(value) {
  if(typeof value!=='string'||!/^https?:\/\//i.test(value)||/[\u0000-\u0020\u007f]/.test(value))throw new Error('Crew URL must be an absolute HTTP or HTTPS URL');
  let url;
  try{url=new URL(value);}catch{throw new Error('Crew URL must be an absolute HTTP or HTTPS URL');}
  if(!['http:','https:'].includes(url.protocol)||url.username||url.password||url.search||url.hash)throw new Error('Crew URL must use HTTP or HTTPS without credentials, query or fragment');
  return url.href.replace(/\/$/,'');
}
export function validateConfig(value) {
  if(!value||typeof value!=='object'||Array.isArray(value))throw new Error('Crew config must be a JSON object');
  const result={...value};
  if(value.url!==undefined)result.url=validateServerUrl(value.url);
  for(const key of ['token','cookie']){
    if(value[key]!==undefined&&(typeof value[key]!=='string'||!value[key]||/[\r\n\u0000]/.test(value[key])))throw new Error('Crew config '+key+' must be a nonempty single-line string');
  }
  if(value.token&&value.cookie)throw new Error('Crew config must contain one credential kind');
  return result;
}
export async function readConfig(file=configPath()) {
  try{return validateConfig(JSON.parse(await readFile(file,'utf8')));}
  catch(error){if(error.code==='ENOENT')return {};throw new Error('Cannot read Crew config: '+error.message);}
}
export async function saveConfig(config,file=configPath()) {
  const validated=validateConfig(config);
  const target=path.resolve(file);
  const folder=path.dirname(target);
  await mkdir(folder,{recursive:true,mode:0o700});
  try{
    const stat=await lstat(target);
    if(!stat.isFile()||stat.isSymbolicLink())throw new Error('Crew config destination must be a regular file');
  }catch(error){if(error.code!=='ENOENT')throw error;}
  const temporary=path.join(folder,'.crew-config-'+randomUUID()+'.tmp');
  let handle;
  try{
    handle=await open(temporary,'wx',0o600);
    await handle.writeFile(JSON.stringify(validated,null,2)+'\n','utf8');
    await handle.close();handle=null;
    await rename(temporary,target);
  }finally{
    if(handle)await handle.close();
    await unlink(temporary).catch(error=>{if(error.code!=='ENOENT')throw error;});
  }
}

