import {commands as auth} from './commands/auth.js';
const booleans=new Set(['json','help','yes','unread','all','preview','local']);
function booleanValue(value,name) {
  if(value==='true')return true;
  if(value==='false')return false;
  throw new Error('--'+name+' accepts only true or false');
}
export function parseArgs(argv) {
  const positional=[],options={};
  for(let i=0;i<argv.length;i++){
    const arg=argv[i];
    if(arg==='--'){positional.push(...argv.slice(i+1));break;}
    if(!arg.startsWith('--')){positional.push(arg);continue;}
    const separator=arg.indexOf('=');
    let name=arg.slice(2,separator<0?undefined:separator);
    if(!/^[a-z][a-z0-9-]*$/.test(name))throw new Error('Invalid option name');
    const negative=name.startsWith('no-')&&booleans.has(name.slice(3));
    if(negative)name=name.slice(3);
    if(Object.hasOwn(options,name))throw new Error('Duplicate option --'+name);
    if(negative){
      if(separator>=0)throw new Error('--no-'+name+' does not accept a value');
      options[name]=false;
    }else if(booleans.has(name))options[name]=separator<0?true:booleanValue(arg.slice(separator+1),name);
    else if(separator>=0)options[name]=arg.slice(separator+1);
    else if(argv[i+1]!==undefined&&!argv[i+1].startsWith('--'))options[name]=argv[++i];
    else throw new Error('Missing value for --'+name);
  }
  return {command:positional[0],args:positional.slice(1),options};
}
function globalHelp(commands) {
  return 'Crew team tracker\nUsage: crew <command> [action] [--url URL] [--token TOKEN] [--config FILE] [--json]\nCommands: '+Object.keys(commands).sort().join(', ')+'\nUse crew <command> --help for actions. Boolean values use --flag=true|false or --no-flag. Destructive changes require --yes. List output includes the next opaque cursor.';
}
export async function runCli(argv,io={write:text=>console.log(text)}) {
  const parsed=parseArgs(argv);
  const commands={...auth};
  for(const lane of ['people','work','insight']){
    const url=new URL(`./commands/${lane}.js`,import.meta.url);
    if(existsSync(url))Object.assign(commands,(await import(url)).commands);
  }
  if(!parsed.command||parsed.command==='help'||(parsed.options.help&&!commands[parsed.command]?.help)){io.write(globalHelp(commands));return;}
  const command=commands[parsed.command];
  if(!command)throw new Error('Unknown command: '+parsed.command);
  if(parsed.options.help){io.write(command.help);return;}
  const file=parsed.options.config??configPath();
  const config=await readConfig(file);
  const client=new CrewClient({...config,url:parsed.options.url??process.env.CREW_URL??config.url,token:parsed.options.token??process.env.CREW_TOKEN??config.token});
  await command({...parsed,client,configFile:file,print:value=>io.write(format(value,parsed.options.json===true))});
}

const segments=new Intl.Segmenter(undefined,{granularity:'grapheme'});
const dangerous=/[\u0000-\u001f\u007f-\u009f\u061c\u200e\u200f\u202a-\u202e\u2066-\u2069]/gu;
export function terminalText(value) {
  return String(value).replace(dangerous,char=>'\\u'+char.codePointAt(0).toString(16).padStart(4,'0'));
}
function wide(code) {
  return code>=0x1100&&(code<=0x115f||code===0x2329||code===0x232a||(code>=0x2e80&&code<=0xa4cf&&code!==0x303f)||(code>=0xac00&&code<=0xd7a3)||(code>=0xf900&&code<=0xfaff)||(code>=0xfe10&&code<=0xfe19)||(code>=0xfe30&&code<=0xfe6f)||(code>=0xff00&&code<=0xff60)||(code>=0xffe0&&code<=0xffe6)||(code>=0x20000&&code<=0x3fffd));
}
function clusterWidth(text) {
  if(/^\p{Mark}+$/u.test(text))return 0;
  if(/\p{Extended_Pictographic}|\p{Regional_Indicator}|\u20e3/u.test(text))return 2;
  return wide(text.codePointAt(0))?2:1;
}
export function displayWidth(value) {
  let width=0;
  for(const item of segments.segment(String(value)))width+=clusterWidth(item.segment);
  return width;
}
export function truncateText(value,width=60) {
  const text=terminalText(value);
  if(displayWidth(text)<=width)return text;
  if(width<1)return '';
  let result='',used=0;
  for(const item of segments.segment(text)){
    const size=clusterWidth(item.segment);
    if(used+size>width-1)break;
    result+=item.segment;used+=size;
  }
  return result+'…';
}
function display(value) {
  if(value==null)return '—';
  if(typeof value!=='object')return terminalText(value);
  return terminalText(JSON.stringify(value));
}
function pad(value,width) {return value+' '.repeat(Math.max(0,width-displayWidth(value)));}
function safeColumn(key) {return !/^(?:password|password_hash|token|cookie|secret|authorization)$/i.test(key);}
export function table(items,columns) {
  if(!items.length)return 'No results';
  const keys=columns??[...new Set(items.flatMap(row=>Object.keys(row??{})))].filter(safeColumn);
  if(!keys.length)return 'No displayable fields';
  const headings=keys.map(key=>truncateText(key));
  const rows=items.map(row=>keys.map(key=>truncateText(display(row?.[key]))));
  const widths=keys.map((key,index)=>Math.max(displayWidth(headings[index]),...rows.map(row=>displayWidth(row[index]))));
  const line=values=>values.map((value,index)=>pad(value,widths[index])).join('  ').trimEnd();
