    const lines=[table(value.items)];
    if(Number.isFinite(value.total))lines.push('Total: '+value.total);
    if(value.nextCursor)lines.push('Next cursor: '+terminalText(value.nextCursor));
    return lines.join('\n');
  }
  if(Array.isArray(value))return table(value);
  if(value&&typeof value==='object')return Object.entries(value).map(([key,item])=>terminalText(key)+': '+display(item)).join('\n');
