test('explicit false and negated confirmation cannot become destructive consent',()=>{
  assert.equal(parseArgs(['issue','delete','x','--yes=false']).options.yes,false);
  assert.equal(parseArgs(['--no-yes','issue','delete','x']).options.yes,false);
  assert.equal(parseArgs(['--yes=true']).options.yes,true);
  assert.equal(parseArgs(['--preview=false','--no-json']).options.preview,false);
});
test('boolean syntax rejects ambiguous values and duplicate positive or negative options',()=>{
  for(const value of ['0','1','','FALSE','perhaps'])assert.throws(()=>parseArgs(['--yes='+value]),/true or false/);
  assert.throws(()=>parseArgs(['--yes','--no-yes']),/Duplicate/);
  assert.throws(()=>parseArgs(['--no-yes=true']),/does not accept/);
  assert.throws(()=>parseArgs(['--url=a','--url=b']),/Duplicate/);
});
test('valued options retain equals negative values and literal arguments after delimiter',()=>{
  const result=parseArgs(['issue','edit','id','--title=a=b','--priority','-1','--','--literal']);
  assert.equal(result.options.title,'a=b');assert.equal(result.options.priority,'-1');assert.deepEqual(result.args,['edit','id','--literal']);
  assert.throws(()=>parseArgs(['--__proto__=bad']),/Invalid/);
