});
test('human columns preserve whole graphemes and account for CJK and emoji display widths',()=>{
  assert.equal(displayWidth('e\u0301'),1);assert.equal(displayWidth('团队'),4);assert.equal(displayWidth('👩‍💻'),2);
  assert.equal(truncateText('👩‍💻alpha',3),'👩‍💻…');assert.equal(truncateText('团队',3),'团…');
  const rows=table([{name:'团队',n:1},{name:'abcd',n:2}]).split('\n');
