test('client classifies malformed JSON redirects and network failures without replay',async()=>{
  for(const [response,code] of [[()=>new Response('{',{headers:{'content-type':'application/json'}}),'INVALID_RESPONSE'],[()=>new Response(null,{status:302,headers:{location:'https://other.test'}}),'REDIRECT_REFUSED']]){
